import{_ as p,V as o,W as c,X as l,Z as n,a1 as a,$ as t,Y as e,F as i}from"./framework-b1bd8911.js";const u={},d=n("p",null,'前面几篇介绍的都是二维码的"生成"，本篇来看一下它的另一半功能——二维码的"解析"，也就是把一张二维码图片反解出里面塞的内容。',-1),r=e(`<h2 id="_1-场景介绍" tabindex="-1"><a class="header-anchor" href="#_1-场景介绍" aria-hidden="true">#</a> 1. 场景介绍</h2><p>二维码解析并不是一个可有可无的功能，实际业务里用得相当多：</p><ul><li>用户上传了一张二维码截图，后端需要判断这张图里到底是一个支付码、一个 URL 还是一段文本；</li><li>生成二维码之后，做一道&quot;生成 -&gt; 解析&quot;的闭环校验，确认生成的二维码确实可扫、内容没被样式折腾丢；</li><li>对第三方提供的二维码图片做内容预检，拦截不合规的跳转链接。</li></ul><p>quick-media 的 qrcode-plugin 底层依赖 zxing，生成用它的编码能力，解析用的就是它的解码能力（<code>MultiFormatReader</code>），插件只是把整个解析流程包装成了一个开箱即用的工具类：<code>QrCodeDeWrapper</code>。</p><h2 id="_2-依赖引入" tabindex="-1"><a class="header-anchor" href="#_2-依赖引入" aria-hidden="true">#</a> 2. 依赖引入</h2><p>与生成篇完全一致，同一个依赖里既包含生成也包含解析：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.github.liuyueyi.media/qrcode-plugin --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>qrcode-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.0.1<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>gradle 用户：</p><div class="language-groovy line-numbers-mode" data-ext="groovy"><pre class="language-groovy"><code><span class="token comment">// https://mvnrepository.com/artifact/com.github.liuyueyi.media/qrcode-plugin</span>
implementation <span class="token string">&#39;com.github.liuyueyi.media:qrcode-plugin:3.0.0&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>相关的测试用例可以在源码中找到：</p>`,10),k={href:"https://github.com/liuyueyi/quick-media/blob/master/plugins/qrcode-plugin/src/test/java/com/github/hui/quick/plugin/test/QrCodeWrapperTest.java",target:"_blank",rel:"noopener noreferrer"},m={href:"https://github.com/liuyueyi/quick-media/blob/master/plugins/qrcode-plugin/src/test/java/com/github/hui/quick/plugin/test/QrDetectTest.java",target:"_blank",rel:"noopener noreferrer"},v=e(`<h2 id="_3-解析接口说明" tabindex="-1"><a class="header-anchor" href="#_3-解析接口说明" aria-hidden="true">#</a> 3. 解析接口说明</h2><p>解析的入口是 <code>QrCodeDeWrapper</code>（De 即 Decode），整个类只有两个静态方法，非常简单：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 方式一：传图片地址，支持本地路径（相对/绝对）与网络地址</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">decode</span><span class="token punctuation">(</span><span class="token class-name">String</span> qrcodeImg<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span><span class="token punctuation">,</span> <span class="token class-name">NotFoundException</span>

<span class="token comment">// 方式二：直接传加载好的 BufferedImage 对象</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">String</span> <span class="token function">decode</span><span class="token punctuation">(</span><span class="token class-name">BufferedImage</span> image<span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">NotFoundException</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>入参 <code>qrcodeImg</code> 走的是 <code>ImageLoadUtil.getImageByPath(path)</code>，因此支持三种姿势：本地绝对路径、classpath 相对路径（测试目录中的 <code>logo.jpg</code> 就是这么加载的）、<code>http</code> 开头的网络地址</li><li>返回值就是二维码中的原始文本内容</li><li><code>IOException</code> 对应图片加载失败；<code>NotFoundException</code> 对应图片中&quot;找不到&quot;可识别的二维码，这是解析失败最常见的异常，调用时务必处理</li></ul><p>内部实现一眼就能看穿，走的是 zxing 的标准解码流程：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">LuminanceSource</span> source <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">BufferedImageLuminanceSource</span><span class="token punctuation">(</span>image<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">BinaryBitmap</span> bitmap <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">BinaryBitmap</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">HybridBinarizer</span><span class="token punctuation">(</span>source<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name">Map</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">DecodeHintType</span><span class="token punctuation">,</span> <span class="token class-name">Object</span><span class="token punctuation">&gt;</span></span> hints <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">LinkedHashMap</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 解码设置编码方式为：utf-8</span>
hints<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token class-name">DecodeHintType</span><span class="token punctuation">.</span><span class="token constant">CHARACTER_SET</span><span class="token punctuation">,</span> <span class="token string">&quot;utf-8&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 优化精度</span>
hints<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token class-name">DecodeHintType</span><span class="token punctuation">.</span><span class="token constant">TRY_HARDER</span><span class="token punctuation">,</span> <span class="token class-name">Boolean</span><span class="token punctuation">.</span><span class="token constant">TRUE</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 复杂模式，开启PURE_BARCODE模式</span>
hints<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token class-name">DecodeHintType</span><span class="token punctuation">.</span><span class="token constant">PURE_BARCODE</span><span class="token punctuation">,</span> <span class="token class-name">Boolean</span><span class="token punctuation">.</span><span class="token constant">TRUE</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">Result</span> result <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">MultiFormatReader</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>bitmap<span class="token punctuation">,</span> hints<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">return</span> result<span class="token punctuation">.</span><span class="token function">getText</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里有三个解码提示（hints），后面排查问题全靠它们，先混个脸熟：</p><table><thead><tr><th>Hint</th><th>值</th><th>作用</th></tr></thead><tbody><tr><td>CHARACTER_SET</td><td>utf-8</td><td>按照什么编码去还原内容，与生成时的编码必须匹配</td></tr><tr><td>TRY_HARDER</td><td>true</td><td>让解码器花更多精力去找二维码，提升识别成功率</td></tr><tr><td>PURE_BARCODE</td><td>true</td><td>声明图片是一张&quot;纯净&quot;的二维码，不做额外的容错识别</td></tr></tbody></table><h2 id="_4-可运行示例" tabindex="-1"><a class="header-anchor" href="#_4-可运行示例" aria-hidden="true">#</a> 4. 可运行示例</h2><h3 id="_4-1-解析本地二维码图片" tabindex="-1"><a class="header-anchor" href="#_4-1-解析本地二维码图片" aria-hidden="true">#</a> 4.1 解析本地二维码图片</h3><p>来自测试类 <code>QrDetectTest#testReadQrCode</code>，加载一张本地图片并反解内容：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testReadQrCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span> <span class="token punctuation">{</span>
    <span class="token class-name">BufferedImage</span> img <span class="token operator">=</span> <span class="token class-name">ImageLoadUtil</span><span class="token punctuation">.</span><span class="token function">getImageByPath</span><span class="token punctuation">(</span><span class="token string">&quot;d://tmp/qq.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">String</span> ans <span class="token operator">=</span> <span class="token class-name">QrCodeDeWrapper</span><span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>img<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>ans<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>等价的简写姿势（一步到位，连图片加载都不用自己写）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testReadQrCodeV2</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> ans <span class="token operator">=</span> <span class="token class-name">QrCodeDeWrapper</span><span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span><span class="token string">&quot;d://tmp/qq.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>ans<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-解析网络二维码图片" tabindex="-1"><a class="header-anchor" href="#_4-2-解析网络二维码图片" aria-hidden="true">#</a> 4.2 解析网络二维码图片</h3><p>来自测试类 <code>QrCodeWrapperTest#testDepaseQrCode</code>，直接传网络图片地址：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testDepaseQrCode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">FormatException</span><span class="token punctuation">,</span> <span class="token class-name">ChecksumException</span><span class="token punctuation">,</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">,</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> img <span class="token operator">=</span> <span class="token string">&quot;https://static.oschina.net/uploads/img/201707/09205944_0PzS.jpg&quot;</span><span class="token punctuation">;</span>

    <span class="token class-name">String</span> ans <span class="token operator">=</span> <span class="token class-name">QrCodeDeWrapper</span><span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>img<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>ans<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>网络图片的解析姿势与本地没有区别，底层会自动下载再解码。不过要注意网络失败、图床失效这类问题，生产环境里更稳妥的做法是自己下载好图片再传 <code>BufferedImage</code> 进去。</p><h3 id="_4-3-生成-解析闭环验证" tabindex="-1"><a class="header-anchor" href="#_4-3-生成-解析闭环验证" aria-hidden="true">#</a> 4.3 生成 -&gt; 解析闭环验证</h3><p>很多小伙伴会在生成二维码之后怀疑&quot;我生成的二维码到底能不能扫&quot;，其实完全可以自己写个闭环校验：生成之后直接反解，看内容是否与预期一致。</p><p>插件自带的 <code>Base64Util</code> 可以在 base64 与图片之间互转，配合使用如下：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">QrDetectTest</span> <span class="token punctuation">{</span>

    <span class="token annotation punctuation">@Test</span>
    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testBase642Ima</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">IOException</span> <span class="token punctuation">{</span>
        <span class="token comment">// 图片转 base64</span>
        <span class="token class-name">BufferedImage</span> bfimg <span class="token operator">=</span> <span class="token class-name">ImageLoadUtil</span><span class="token punctuation">.</span><span class="token function">getImageByPath</span><span class="token punctuation">(</span><span class="token string">&quot;logo.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">String</span> str <span class="token operator">=</span> <span class="token class-name">Base64Util</span><span class="token punctuation">.</span><span class="token function">encode</span><span class="token punctuation">(</span>bfimg<span class="token punctuation">,</span> <span class="token string">&quot;png&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">// base64 转回图片</span>
        <span class="token class-name">BufferedImage</span> img <span class="token operator">=</span> <span class="token class-name">Base64Util</span><span class="token punctuation">.</span><span class="token function">decode2Img</span><span class="token punctuation">(</span>str<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;img&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>把这条链路串起来，就是完整的&quot;生成-解析&quot;闭环：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">genAndParse</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">throws</span> <span class="token class-name">Exception</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> msg <span class="token operator">=</span> <span class="token string">&quot;https://liuyueyi.github.io/hexblog/&quot;</span><span class="token punctuation">;</span>

    <span class="token comment">// 第一步：生成二维码，直接拿 BufferedImage</span>
    <span class="token class-name">BufferedImage</span> qrImg <span class="token operator">=</span> <span class="token class-name">QrCodeGenWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setW</span><span class="token punctuation">(</span><span class="token number">300</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setPadding</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">asBufferedImage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// 第二步：解析回内容</span>
    <span class="token class-name">String</span> ans <span class="token operator">=</span> <span class="token class-name">QrCodeDeWrapper</span><span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>qrImg<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>ans<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">// 输出：https://liuyueyi.github.io/hexblog/</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>2.x 的 <code>QrCodeGenWrapper</code> Builder 提供了 <code>asBufferedImage()</code> 方法，直接返回 <code>BufferedImage</code>，不需要落盘再读盘</li><li>3.x 的 <code>QrCodeGenV3</code> 则对应 <code>asImg()</code>，同样返回 <code>BufferedImage</code></li><li>解析出来的内容与输入 <code>msg</code> 一致，说明这张二维码至少在 zxing 眼里是&quot;可扫&quot;的</li></ul><h3 id="_4-4-异常处理姿势" tabindex="-1"><a class="header-anchor" href="#_4-4-异常处理姿势" aria-hidden="true">#</a> 4.4 异常处理姿势</h3><p>解析与生成不同，&quot;失败&quot;是一种正常输入（比如用户随手传了张风景照），所以异常处理要当成业务逻辑的一部分来写：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">parseWithError</span><span class="token punctuation">(</span><span class="token class-name">String</span> qrPath<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">try</span> <span class="token punctuation">{</span>
        <span class="token class-name">String</span> content <span class="token operator">=</span> <span class="token class-name">QrCodeDeWrapper</span><span class="token punctuation">.</span><span class="token function">decode</span><span class="token punctuation">(</span>qrPath<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;解析结果: &quot;</span> <span class="token operator">+</span> content<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">IOException</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 图片加载失败：路径错误、网络异常、格式不支持等</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;图片加载失败: &quot;</span> <span class="token operator">+</span> e<span class="token punctuation">.</span><span class="token function">getMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span> <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name">NotFoundException</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 图片中识别不到二维码：可能根本没有二维码，也可能样式太花哨</span>
        <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;未识别到二维码&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>提示：<code>QrCodeDeWrapper#decode(BufferedImage)</code> 的方法签名只声明了 <code>NotFoundException</code>，<code>NotFoundException</code> 本身是 zxing 的受检异常；而 <code>decode(String)</code> 额外抛 <code>IOException</code>。按上面的姿势两个都接住最稳妥。</p></blockquote><h2 id="_5-注意点" tabindex="-1"><a class="header-anchor" href="#_5-注意点" aria-hidden="true">#</a> 5. 注意点</h2><p>解析虽然接口简单，但&quot;能不能解出来&quot;受很多因素影响，下面几个点是实际使用中的高频坑：</p><ul><li><strong>编码要对上</strong>：解码器内部固定按 <code>utf-8</code> 解析。如果二维码生成时通过 <code>setCode()</code> 指定过其他编码（比如 gbk），解析出来就是乱码甚至直接解析失败。所以自家生成的二维码请保持默认 utf-8</li><li><strong>PURE_BARCODE 模式对&quot;花哨&quot;二维码不友好</strong>：解码 hints 中开启了 <code>PURE_BARCODE</code>，它假设图片是一张干净的二维码。对于带大面积背景图、艺术化码元、深色滤镜的二维码，识别成功率会下降。如果失败，可以尝试先把图片裁剪出二维码所在区域再解析</li><li><strong>遮挡与对比度</strong>：中间的 logo 太大（超过二维码约 1/5~1/3 的区域）、码元与背景色对比度太低（比如浅灰配浅蓝），都会导致识别失败。生成侧的规避方式：logo 别超过 <code>setLogoRate</code> 的合理范围、容错级别用 H</li><li><strong>图片质量</strong>：图片过小、模糊、有噪点都会影响解码，建议二维码输出尺寸不小于 200x200；用户上传的截图常见&quot;压得特别小&quot;的情况，必要时先放大再解析</li><li><strong>gif 动图只取第一帧</strong>：<code>decode(String)</code> 内部走的是 <code>ImageIO.read()</code>，对于 gif 只会读取第一帧。动态二维码的第一帧通常就是完整的二维码，所以一般没问题，但如果是自定义素材请保证第一帧可扫</li><li><strong>解析接口与生成接口解耦</strong>：<code>QrCodeDeWrapper</code> 只依赖图片本身，不关心二维码是谁生成的。所以它既能解析本插件生成的二维码，也能解析微信、支付宝等任何标准二维码</li><li><strong>只返回文本</strong>：<code>decode</code> 返回的是 <code>Result#getText()</code>，即二维码的字符串内容。如果需要拿到二维码的纠错级别、版本号等元信息，就得自己基于 zxing 的 <code>MultiFormatReader</code> 扩展了</li></ul><h2 id="_6-小结" tabindex="-1"><a class="header-anchor" href="#_6-小结" aria-hidden="true">#</a> 6. 小结</h2><p>本篇介绍了 qrcode-plugin 中二维码信息解析的使用姿势：核心入口是 <code>QrCodeDeWrapper#decode</code>，支持本地图片、网络图片与 <code>BufferedImage</code> 三种输入，底层由 zxing 的 <code>MultiFormatReader</code> 完成，解码时固定 utf-8 + TRY_HARDER + PURE_BARCODE 三个提示。</p><p>配合生成侧的 <code>asBufferedImage()</code>，可以低成本实现&quot;生成 -&gt; 解析&quot;的闭环自测；配合 <code>Base64Util</code>，也能处理 base64 形式的二维码图片。解析失败在业务上是常态而非异常，记得把 <code>NotFoundException</code> 当成一种正常返回来处理。</p><p>至此，二维码的生成与解析就都介绍完了，完整的生成侧定制能力请回顾前面几篇：基本姿势、logo/背景/前置图、矢量二维码与动态二维码。</p>`,36);function g(b,h){const s=i("ExternalLinkIcon");return o(),c("div",null,[d,l(" more "),r,n("ul",null,[n("li",null,[n("a",k,[a("QrCodeWrapperTest | GitHub"),t(s)])]),n("li",null,[n("a",m,[a("QrDetectTest | GitHub"),t(s)])])]),v])}const y=p(u,[["render",g],["__file","3.x二维码信息解析使用示例.html.vue"]]);export{y as default};
